previewCss:
.darma-loader-darma-b13-toggle-switch { --accent: var(--loader-color, #16a34a); --accent-2: var(--loader-secondary-color, #cbd5e1); width: var(--loader-size, 88px); height: calc(var(--loader-size, 88px) * .5); position: relative; border-radius: 999px; box-shadow: inset 0 2px 5px rgba(15, 23, 42, .28); animation: darma-loader-darma-b13-toggle-switch-track-tint calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b13-toggle-switch span { position: absolute; top: 9%; width: 44%; height: 82%; border-radius: 50%; background: #f8fafc; box-shadow: 0 2px 5px rgba(15, 23, 42, .3); animation: darma-loader-darma-b13-toggle-switch-knob-slide calc(var(--loader-speed, 1s) * 2.2) cubic-bezier(.45, 1.5, .5, 1) infinite; }
@keyframes darma-loader-darma-b13-toggle-switch-track-tint { 0%, 20% { background: color-mix(in srgb, #000 14%, var(--accent-2)); } 46%, 70% { background: var(--accent); } 96%, 100% { background: color-mix(in srgb, #000 14%, var(--accent-2)); } }
@keyframes darma-loader-darma-b13-toggle-switch-knob-slide { 0%, 20% { left: 3%; } 46%, 70% { left: 53%; } 96%, 100% { left: 3%; } }

